settings.custom_css:
selector .ak-nowrap .elementor-heading-title { white-space: nowrap; }
selector .ak-plan-left .ak-g { color: #8C1A17; }
/* dorado de 3 tonos (solo color) */
selector .ak-oro-text .elementor-heading-title { background-image: linear-gradient(to bottom right, #8C1A17 0%, #B20505 50%, #8C1A17 100%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
selector .ak-oro-box .elementor-icon { background-image: linear-gradient(to bottom right, #8C1A17 0%, #B20505 50%, #8C1A17 100%) !important; }
selector .ak-plan-dl .elementor-button { border-image: linear-gradient(to bottom right, #8C1A17 0%, #B20505 50%, #8C1A17 100%) 1 !important; }
@media (max-width: 1024px) { selector .ak-dk { display: none; } }
selector .ak-mb { display: none; }
@media (max-width: 767px) {
  selector .ak-mb { display: inline; }
  selector .ak-dk { display: none; }
  /* 3 datos en columnas iguales y centrados, como el XD móvil */
  selector .ak-stats-row { display: grid !important; grid-template-columns: repeat(3, 1fr); width: 100%; }
  selector .ak-stat { align-items: center !important; text-align: center; padding-left: 6px !important; padding-right: 6px !important; width: auto !important; }
  selector .ak-stat:first-child { padding-left: 0 !important; }
  selector .ak-stat .elementor-widget-icon .elementor-icon-wrapper, selector .ak-stat .elementor-heading-title { text-align: center; }
  selector .ak-nowrap .elementor-heading-title { white-space: normal; }
  selector .ak-plan-dl { align-self: center; }
}
selector .ak-stat { --width: auto; width: auto; flex: 0 0 auto; }
selector .ak-stats-row { --width: 100%; flex-wrap: nowrap; }
selector .ak-plan-left, selector .ak-plan-right { min-width: 0; }
selector .elementor-widget-text-editor p:last-child { margin-bottom: 0; }

selector { counter-reset: mod; border-top: 1px solid #CCD0D4; }
/* scroll vertical: se ven 4 módulos completos (4 x 155px desktop / 4 x 117px laptop); sin barras */
selector .e-n-accordion { max-height: 620px; overflow-y: auto; overflow-x: hidden;
  scrollbar-width: none; -ms-overflow-style: none; }
selector .e-n-accordion::-webkit-scrollbar { display: none; width: 0; height: 0; }
selector .e-n-accordion-item > .e-con, selector .e-n-accordion-item > [role="region"] { border: 0 !important; background: none !important; --border-width: 0; margin: 0 !important; }
selector .e-n-accordion-item { counter-increment: mod; border-bottom: 1px solid #CCD0D4; padding: 0 !important; margin: 0 !important; }

/* cabecera: columna "Módulo + número" centrada, título y "Ver contenido +" / "Ocultar −" (líneas finas como el XD) */
selector .e-n-accordion-item-title { display: grid !important; grid-template-columns: 100px minmax(0, 1fr) auto; grid-template-rows: 28px 66px; column-gap: 20px; row-gap: 0;
  align-items: start; padding: 30px 0 30px 0 !important; border: 0 !important; background: none !important; cursor: pointer; list-style: none; }
selector .e-n-accordion-item-title::-webkit-details-marker { display: none; }
selector .e-n-accordion-item-title::before { content: "Módulo"; grid-column: 1; grid-row: 1; justify-self: center; margin-bottom: 4px;
  font: 300 16px/24px Inter, sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #8C1A17; }
selector .e-n-accordion-item-title::after { content: counter(mod, decimal-leading-zero); grid-column: 1; grid-row: 2; justify-self: center;
  font: 500 50px/1.1 Oswald, sans-serif; letter-spacing: -.032em; color: #8C1A17; }
selector .e-n-accordion-item-title-header { grid-column: 2; grid-row: 2; padding-top: 8px; max-width: 480px; }
selector .e-n-accordion-item-title-text { font: 600 24px/29px Oswald, sans-serif !important; text-transform: uppercase; color: #070E21 !important; }
selector .e-n-accordion-item-title-icon { grid-column: 3; grid-row: 2; padding-top: 10px; display: flex !important; align-items: center; }
selector .e-n-accordion-item:not([open]) .e-n-accordion-item-title-icon .e-opened,
selector .e-n-accordion-item[open] .e-n-accordion-item-title-icon .e-closed { display: none !important; }
selector .e-n-accordion-item[open] .e-n-accordion-item-title-icon .e-opened,
selector .e-n-accordion-item:not([open]) .e-n-accordion-item-title-icon .e-closed { display: inline-flex !important; }
selector .e-n-accordion-item-title-icon > span { align-items: center; gap: 12px;
  font: 500 16px/1 Inter, sans-serif; letter-spacing: .1em; text-transform: uppercase; color: #808591; white-space: nowrap; }
selector .e-n-accordion-item-title-icon .e-closed::before { content: "Ver contenido"; }
selector .e-n-accordion-item-title-icon .e-opened::before { content: "Ocultar"; }
selector .e-n-accordion-item-title-icon > span::after { content: ""; width: 12px; height: 12px; flex: 0 0 12px;
  background: linear-gradient(#808591, #808591) center / 12px 1px no-repeat; }
selector .e-n-accordion-item-title-icon .e-closed::after { background: linear-gradient(#808591, #808591) center / 12px 1px no-repeat, linear-gradient(#808591, #808591) center / 1px 12px no-repeat; }
selector .e-n-accordion-item-title-icon i, selector .e-n-accordion-item-title-icon svg { display: none !important; }

/* contenido: alineado con el título, tarjetas como el XD */
selector .ak-mod-body { padding-left: 120px !important; padding-bottom: 30px !important; }
selector .ak-mod-body > .elementor-widget-text-editor { font: 300 18px/28px Inter, sans-serif !important; letter-spacing: .01em; color: #0C1522; }
selector .ak-mod-body > .elementor-widget-text-editor p { font: inherit !important; }
selector .ak-mod-body .elementor-heading-title { font: 600 20px/1.4 Montserrat, sans-serif !important; color: #070908 !important; }
selector .ak-mod-body .e-con .elementor-widget-text-editor, selector .ak-mod-body .e-con .elementor-widget-text-editor p { font: 300 16px/24px Inter, sans-serif !important; letter-spacing: .01em; color: #070908; }
selector .ak-mod-body > .e-con > .e-con:first-child { background-color: #EBEFF2 !important; }
selector .ak-mod-body > .e-con > .e-con:last-child { background-color: #EDDCDC !important; }

@media (max-width: 1366px) {
  selector .e-n-accordion { max-height: 468px; }
  selector .e-n-accordion-item-title { grid-template-columns: 72px minmax(0, 1fr) auto; grid-template-rows: 22px 50px; column-gap: 14px; padding: 22px 0 !important; }
  selector .e-n-accordion-item-title::before { font-size: 11px; line-height: 18px; }
  selector .e-n-accordion-item-title::after { font-size: 36px; }
  selector .e-n-accordion-item-title-header { padding-top: 6px; max-width: 380px; }
  selector .e-n-accordion-item-title-text { font-size: 18px !important; line-height: 22px !important; }
  selector .e-n-accordion-item-title-icon { padding-top: 8px; }
  selector .e-n-accordion-item-title-icon > span { font-size: 14px; }
  selector .ak-mod-body { padding-left: 86px !important; padding-bottom: 24px !important; }
  selector .ak-mod-body > .elementor-widget-text-editor { font-size: 16px !important; }
  selector .ak-mod-body .elementor-heading-title { font-size: 16px !important; }
  selector .ak-mod-body .e-con .elementor-widget-text-editor, selector .ak-mod-body .e-con .elementor-widget-text-editor p { font-size: 16px !important; line-height: 22px !important; }
}
@media (max-width: 767px) {
  selector .e-n-accordion { max-height: none; overflow: visible; }
  selector .e-n-accordion-item-title { grid-template-columns: 50px minmax(0, 1fr) auto; grid-template-rows: auto auto; column-gap: 12px; padding: 18px 0 !important; }
  selector .e-n-accordion-item-title::before { font-size: 10px; line-height: 14px; }
  selector .e-n-accordion-item-title::after { font-size: 36px; }
  selector .e-n-accordion-item-title-header { padding-top: 4px; max-width: none; }
  selector .e-n-accordion-item-title-text { font: 500 16px/20px Oswald, sans-serif !important; letter-spacing: -.01em; }
  selector .e-n-accordion-item-title-icon { padding-top: 6px; }
  selector .e-n-accordion-item-title-icon > span { font-size: 12px; gap: 8px; }
  selector .ak-mod-body { padding-left: 0 !important; padding-bottom: 20px !important; }
  selector .ak-mod-body > .elementor-widget-text-editor { font-size: 14px !important; line-height: 22px !important; }
  selector .ak-mod-body .elementor-heading-title { font-size: 16px !important; }
  selector .ak-mod-body .e-con .elementor-widget-text-editor, selector .ak-mod-body .e-con .elementor-widget-text-editor p { font-size: 14px !important; line-height: 22px !important; }
}
